import gridwell


def local_maxima(rows):
    """Return the (row, column) positions whose value is larger than all of the values around them."""
    grid = gridwell.Grid(rows)
    n, m = grid.shape
    return [(r, c) for r in range(n) for c in range(m)
            if all(grid.cell(r, c) > v for v in grid.neighbors(r, c))]


def locate_max(grid):
    """Find the maximum value in a grid and return its position."""
    max_value = max(grid.values())
    return grid.locate(max_value, "max")


def smooth(grid, sigma, boundary="periodic"):
    """Smooth a grid using a Gaussian filter."""
    from scipy.ndimage.filters import gaussian_filter
    return gaussian_filter(grid, sigma, mode="wrap", cval=0, boundary=boundary)


def rotate(grid, turns):
    """Rotate a grid by a given number of turns."""
    if not isinstance(turns, int):
        raise TypeError("turns must be an integer")
    if turns < 0:
        turns = -turns
    return grid.rotate(turns)
